import { _common } from "./_common.js";
import { _evt } from "./_evt.js";

export class _core {
    /** @this {Jdm} */
    static jdm_append(elementList) {
        if (Array.isArray(elementList)) {
            for (const element of elementList) {
                this.node.appendChild(element);
            }
        } else if (elementList) {
            this.node.appendChild(elementList);
        }
        return this.node;
    }

    /** @this {Jdm} */
    static jdm_prepend(elementList) {
        const firstChild = this.node.firstElementChild;

        if (Array.isArray(elementList)) {
            for (const element of elementList) {
                this.node.prepend(element);
            }
        } else if (elementList) {
            this.node.prepend(elementList);
        }
        return this.node;
    }

    /** @this {Jdm} */
    static jdm_appendBefore(elementList) {
        elementList = Array.isArray(elementList) ? elementList : [elementList];
        const parent = this.node.parentNode;
        if (!parent) {
            console.warn("[JDM] jdm_appendBefore: node has no parent");
            return this.node;
        }
        for (const element of elementList) {
            parent.insertBefore(element, this.node);
        }
        return this.node;
    }

    /** @this {Jdm} */
    static jdm_appendAfter(elementList) {
        elementList = Array.isArray(elementList) ? elementList : [elementList];
        const parent = this.node.parentNode;
        if (!parent) {
            console.warn("[JDM] jdm_appendAfter: node has no parent");
            return this.node;
        }
        // Native DOM has no `insertAfter` — use `insertBefore` with nextSibling (null = append at end).
        // Iterate in reverse so the elements end up in passed order after this.node.
        for (let i = elementList.length - 1; i >= 0; i--) {
            parent.insertBefore(elementList[i], this.node.nextSibling);
        }
        return this.node;
    }

    /** @this {Jdm} */
    static jdm_setAttribute(attribute, value = "") {
        if (!attribute) {
            console.warn("[JDM] jdm_setAttribute: empty attribute name");
            return this.node;
        }
        // value=null senza fix sarebbe scritto come stringa "null" — neutralizziamo
        this.node.setAttribute(attribute, value == null ? "" : value);
        return this.node;
    }

    /** @this {Jdm} */
    static jdm_getAttribute(attribute) {
        return this.node.getAttribute(attribute);
    }

    /** @this {Jdm} */
    static jdm_removeAttribute(attribute) {
        this.node.removeAttribute(attribute);
        return this.node;
    }

    /** @this {Jdm} */
    static jdm_addId(id) {
        this.node.setAttribute("id", id);
        return this.node;
    }

    /** @this {Jdm} */
    static jdm_addClassList(classList) {
        if (Array.isArray(classList)) {
            for (const cls of classList) {
                this.node.classList.add(cls);
            }
        } else if (classList) {
            this.node.classList.add(classList);
        }
        return this.node;
    }

    /** @this {Jdm} */
    static jdm_removeClassList(classList) {
        if (Array.isArray(classList)) {
            for (const cls of classList) {
                this.node.classList.remove(cls);
            }
        } else if (classList) {
            this.node.classList.remove(classList);
        }
        return this.node;
    }

    /** @this {Jdm} */
    static jdm_toggleClassList(classList) {
        if (Array.isArray(classList)) {
            for (const cls of classList) {
                this.node.classList.toggle(cls);
            }
        } else if (classList) {
            this.node.classList.toggle(classList);
        }
        return this.node;
    }

    /** @this {Jdm} */
    static jdm_findClassList(classList, some = false) {
        classList = Array.isArray(classList) ? classList : [classList];
        return some ? classList.some(cls => this.node.classList.contains(cls)) : classList.every(cls => this.node.classList.contains(cls));
    }

    /** @this {Jdm} */
    static jdm_empty() {
        if (this.tag === "input" && (this.node.type === "checkbox" || this.node.type === "radio")) {
            this.node.checked = false;
        } else if (this.tag === "input" || this.tag === "textarea") {
            this.node.value = null;
        } else if (this.tag === "form") {
            if (this.node.elements?.length > 0) {
                for (const element of this.node.elements) {
                    if (element.type === "checkbox" || element.type === "radio") {
                        element.checked = false;
                    } else if (element.type === "select-multiple" || element.type === "select-one") {
                        for (const option of element.options) {
                            element.value = null;
                        }
                    } else {
                        element.value = "";
                    }
                }
            }
        } else {
            this.node.innerHTML = "";
        }
        return this.node;
    }

    /** @this {Jdm} */
    static jdm_destroy() {
        this.node.remove();
        return this.node;
    }

    /** @this {Jdm} */
    static jdm_validate() {
        if (typeof this.node.checkValidity !== "function") {
            console.warn("[JDM] jdm_validate: node has no checkValidity()");
            return this.node;
        }
        const validity = this.node.checkValidity();
        this.jdm_genEvent("validate", validity);
        return this.node;
    }

    /** @this {Jdm} */
    static jdm_setStyle(style, value) {
        this.node.style[style] = value;
        return this.node;
    }

    /** @this {Jdm} */
    static jdm_extendNode(name, object = null) {
        if (name === "__proto__" || name === "prototype" || name === "constructor") {
            console.warn(`[JDM] jdm_extendNode: refused unsafe name "${name}" (prototype pollution)`);
            return this.node;
        }
        this.node[name] = object;
        return this.node;
    }

    /** @this {Jdm} */
    static jdm_innerHTML(value) {
        this.node.innerHTML = value;
        return this.node;
    }

    /** @this {Jdm} */
    static jdm_binding(el, event = "input", twoWayDataBinding = true) {
        let elementList = [];

        if (Array.isArray(el)) {
            elementList = elementList.concat(el);
        } else {
            elementList.push(el);
        }

        for (const element of elementList) {
            if (
                element.tagName.toLowerCase() === "input" ||
                element.tagName.toLowerCase() === "select" ||
                element.tagName.toLowerCase() === "textarea"
            ) {
                this.node.addEventListener(event, () => {
                    element.jdm_setValue(this.jdm_getValue());
                });
            } else {
                this.node.addEventListener(event, () => {
                    element.jdm_innerHTML(this.jdm_getValue());
                });
            }

            if (twoWayDataBinding) {
                const elementListTmp = elementList.filter(elementTmp => elementTmp !== element);
                elementListTmp.push(this.node);
                // single recursive call: bind element → [others + this.node]. No inner loop (was N×N duplicate).
                element.jdm_binding(elementListTmp, event, false);
            }
        }

        return this.node;
    }

    /** @this {Jdm} */
    static jdm_setValue(value, tooBoolean = true) {
        if (tooBoolean) {
            try {
                value = value.toBoolean();
            } catch (e) {
                value = value;
            }
        }

        if (this.node.type === "checkbox" || this.node.type === "radio") {
            this.node.checked = value;
        } else if (this.tag === "form") {
            const setValue = (el, value) => {
                if (el.type === "checkbox" || el.type === "radio") {
                    // value falsy (null/undefined/0/""/false) → unchecked; tutto il resto truthy → checked
                    el.checked = value == null ? false : !!value;
                } else {
                    // preserva 0 / false / "" come stringa rappresentativa; null/undefined → ""
                    el.value = value == null ? "" : value;
                }
            };

            const findElement = (form, name) => {
                return form.querySelectorAll(`[name="${name}"]`);
            };

            const populateForm = (form, data, prefix = "") => {
                if (data == null || typeof data !== "object") return;
                for (const key of Object.keys(data)) {
                    const value = data[key];
                    const name = prefix ? `${prefix}[${key}]` : key;
                    const elementList = findElement(form, Array.isArray(value) ? `${name}[]` : name);
                    if (elementList?.length > 0) {
                        for (const element of elementList) {
                            if (Array.isArray(value)) {
                                const checkboxes = form.querySelectorAll(`[name="${name}[]"]`);
                                checkboxes.forEach(checkbox => {
                                    setValue(checkbox, value.includes(checkbox.value));
                                });
                            } else if (value !== null && typeof value === "object") {
                                populateForm(form, value, name);
                            } else {
                                setValue(element, value);
                            }
                        }
                    } else if (value !== null && typeof value === "object") {
                        populateForm(form, value, name);
                    }
                }
            };
            populateForm(this.node, value);
        } else {
            if (this.node.jdm_getAttribute("type") === "number" || this.node.jdm_getAttribute("type") === "range") {
                const num = value * 1;
                if (Number.isNaN(num)) {
                    console.warn(`[JDM] jdm_setValue: non-numeric value "${value}" on number/range input — skipped`);
                } else {
                    this.node.value = num;
                }
            } else {
                this.node.value = value;
            }
        }

        return this.node;
    }

    /**
     * Variante di setValue senza coerce automatico via `toBoolean()`.
     * Equivalente a `jdm_setValue(value, false)` ma con default esplicito.
     * @this {Jdm}
     */
    static jdm_setValueRaw(value) {
        return _core.jdm_setValue.call(this, value, false);
    }

    /**
     * Ritorna il valore RAW del campo senza coerce magic ("null" → null, FormData split, ecc.).
     * Per form, ritorna FormData direttamente. Per altri input, ritorna node.value (string).
     * @this {Jdm}
     */
    static jdm_getValueRaw() {
        if (this.tag === "form") return new FormData(this.node);
        if (this.tag === "input" && (this.node.type === "checkbox" || this.node.type === "radio")) {
            return this.node.checked;
        }
        return this.node.value;
    }

    /**
     * Ritorna il valore come Number per input number/range. Per altri tipi ritorna NaN.
     * @this {Jdm}
     * @returns {number}
     */
    static jdm_getValueAsNumber() {
        if (typeof this.node.valueAsNumber === "number") return this.node.valueAsNumber;
        const n = Number(this.node.value);
        return n;
    }

    /** @this {Jdm} */

    static jdm_getValue() {
        if (this.tag === "input" && (this.node.type === "checkbox" || this.node.type === "radio")) {
            return this.node.checked;
        } else if (this.tag === "form") {
            const formData = new FormData(this.node);
            const json = {};

            for (let [key, value] of formData.entries()) {
                value = value === "" ? null : value;
                value = value === "null" ? null : value;
                let currentObj = json;
                const keys = key.split(/\[|\]\[|\]/).filter(Boolean);
                const lastKey = keys.pop();

                for (let i = 0; i < keys.length; i++) {
                    const currentKey = keys[i];
                    if (!currentObj[currentKey]) {
                        currentObj[currentKey] = isNaN(keys[i + 1]) ? {} : [];
                    }
                    currentObj = currentObj[currentKey];
                }

                if (lastKey === "") {
                    if (!currentObj.length) {
                        currentObj.length = 0;
                    }
                    currentObj[currentObj.length++] = value;
                } else if (Array.isArray(currentObj[lastKey])) {
                    currentObj[lastKey].push(value);
                } else if (currentObj[lastKey]) {
                    currentObj[lastKey] = [currentObj[lastKey], value];
                } else {
                    if (key.endsWith("[]")) {
                        if (value) {
                            currentObj[lastKey] = new Array();
                            currentObj[lastKey].push(value);
                        }
                    } else {
                        currentObj[lastKey] = value;
                    }
                }
            }
            return json;
        } else if (this.tag === "select") {
            return this.node.value;
        } else {
            return this.node.value;
        }
    }

    /** @this {Jdm} */
    static jdm_genEvent(name, data = null, propagateToParents = true) {
        _common.genEvent(this.node, name, data, propagateToParents);
        return this.node;
    }

    /** @this {Jdm} */
    static jdm_addEventListener(name, fn = () => {}) {
        this.node.addEventListener(name, fn);
        return this.node;
    }

    /** @this {Jdm} */
    static jdm_removeEventListener(name, fn = () => {}) {
        this.node.removeEventListener(name, fn);
        return this.node;
    }

    /** @this {Jdm} */
    static jdm_extendChildNode() {
        if (this.node?.jdm_childNode && Object.entries(this.node.jdm_childNode).length > 0) {
            for (const [key, value] of Object.entries(this.node.jdm_childNode)) {
                this.node.jdm_extendNode(key, value);
            }
        }

        return this.node;
    }

    /** @this {Jdm} */
    static jdm_submit() {
        const event = new Event("submit", { cancelable: true, bubbles: true });
        if (!this.node.dispatchEvent(event)) return this.node;
        try {
            this.node.submit();
        } catch (e) {
            throw new Error(`Element must be a form: ${e}`);
        }
        return this.node;
    }

    /** @this {Jdm} */
    static jdm_onInput(fn = () => {}, opt) {
        _evt.jdm_onElement(this.node, "input", fn, opt);
        return this.node;
    }

    /** @this {Jdm} */
    static jdm_onChange(fn = () => {}, opt) {
        _evt.jdm_onElement(this.node, "change", fn, opt);
        return this.node;
    }

    /** @this {Jdm} */
    static jdm_onSelect(fn = () => {}, opt) {
        _evt.jdm_onElement(this.node, "select", fn, opt);
        return this.node;
    }

    /** @this {Jdm} */
    static jdm_onDebounce(fn = () => {}, timeout = this.defaultDebounceTime, method = "input", opt) {
        _evt.jdm_onElement(this.node, method, _common.debounce(fn, timeout), opt);
        return this.node;
    }

    /** @this {Jdm} */
    static jdm_onClick(fn = () => {}, opt) {
        _evt.jdm_onElement(this.node, "click", fn, opt);
        return this.node;
    }

    /** @this {Jdm} */
    static jdm_onRightClick(fn = () => {}, opt) {
        _evt.jdm_onElement(this.node, "contextmenu", fn, opt);
        return this.node;
    }

    /** @this {Jdm} */
    static jdm_onDoubleClick(fn = () => {}, opt) {
        _evt.jdm_onElement(this.node, "dblclick", fn, opt);
        return this.node;
    }

    /** @this {Jdm} */
    static jdm_onInvalid(fn = () => {}, opt) {
        _evt.jdm_onElement(this.node, "invalid", fn, opt);
        return this.node;
    }

    /** @this {Jdm} */
    static jdm_onLoad(fn = () => {}, opt) {
        _evt.jdm_onElement(this.node, "load", fn, opt);
        return this.node;
    }

    /** @this {Jdm} */
    static jdm_onError(fn = () => {}, opt) {
        _evt.jdm_onElement(this.node, "error", fn, opt);
        return this.node;
    }

    /** @this {Jdm} */
    static jdm_onSubmit(fn = e => {}, opt) {
        _evt.jdm_onElement(this.node, "submit", fn, opt);
        return this.node;
    }
    /** @this {Jdm} */
    static jdm_setDebounceTime(time = this.defaultDebounceTime) {
        this.defaultDebounceTime = time;
        return this.node;
    }

    /**
     * Promise-wrapper su un singolo evento. Risolve con l'oggetto event al primo fire.
     * @this {Jdm}
     * @param {string} eventName
     * @param {Object} [opt]
     * @param {number} [opt.timeout]
     * @param {AbortSignal} [opt.signal]
     * @returns {Promise<Event>}
     */
    static jdm_waitFor(eventName, opt = {}) {
        return new Promise((resolve, reject) => {
            const node = this.node;
            let timer = null;
            const handler = e => {
                if (timer) clearTimeout(timer);
                node.removeEventListener(eventName, handler);
                resolve(e);
            };
            node.addEventListener(eventName, handler, { once: true });
            if (opt.timeout && opt.timeout > 0) {
                timer = setTimeout(() => {
                    node.removeEventListener(eventName, handler);
                    reject(new Error(`[JDM] jdm_waitFor: timeout after ${opt.timeout}ms waiting for "${eventName}"`));
                }, opt.timeout);
            }
            if (opt.signal) {
                opt.signal.addEventListener(
                    "abort",
                    () => {
                        if (timer) clearTimeout(timer);
                        node.removeEventListener(eventName, handler);
                        reject(new Error("[JDM] jdm_waitFor: aborted"));
                    },
                    { once: true },
                );
            }
        });
    }

    /**
     * Event delegation: registra un listener sul node che fa match su `selector`.
     * Pure addition. Ritorna funzione di unsubscribe.
     * @this {Jdm}
     * @param {string} eventName
     * @param {string} selector
     * @param {function(Event, HTMLElement): void} fn
     * @returns {function(): void} unsubscribe
     */
    static jdm_delegate(eventName, selector, fn) {
        const node = this.node;
        const handler = e => {
            const target = e.target.closest(selector);
            if (target && node.contains(target)) {
                fn(e, target);
            }
        };
        node.addEventListener(eventName, handler);
        return () => node.removeEventListener(eventName, handler);
    }

    /**
     * Batcha una serie di operazioni DOM dentro un singolo requestAnimationFrame.
     * Pure addition.
     * @this {Jdm}
     * @param {function(HTMLElement): void} fn
     * @returns {Promise<HTMLElement>}
     */
    static jdm_batch(fn) {
        return new Promise(resolve => {
            const node = this.node;
            const raf = typeof requestAnimationFrame === "function" ? requestAnimationFrame : cb => setTimeout(cb, 16);
            raf(() => {
                try {
                    fn(node);
                } catch (e) {
                    console.warn("[JDM] jdm_batch: errore nel callback —", e);
                }
                resolve(node);
            });
        });
    }
}
